after = json.load(sys.stdin)

# Also get baseline by re-reading - but baseline is corrupted, let's just compare what we know
# Print the after-cpm resolved versions
for proj in after.get('projects', []):
    name = proj['path'].split('/')[-1]
    for fw in proj.get('frameworks', []):
        for pkg in fw.get('topLevelPackages', []):
            print(f'{name}: {pkg[\"id\"]} requested={pkg.get(\"requestedVersion\",\"?\")} resolved={pkg.get(\"resolvedVersion\",\"?\")}')" 2>&1

